//! The answers one request returns, and how a response body becomes them.
//!
//! Decoding follows the Python SDK's dispatch path: one pass reads the
//! envelope, then each answer is read on its own. An answer type the API added
//! is skipped with a warning rather than failing the call, an unknown field is
//! ignored, and a field the SDK cannot read is named by a dotted path such as
//! `answers.tone.confidence`.

use std::borrow::Cow;
use std::collections::BTreeMap;

use indexmap::IndexMap;
use reqwest::header::HeaderMap;
use serde::Deserialize;
use serde_json::Value;
use serde_json::value::RawValue;

use crate::Result;
use crate::error::{Error, REQUEST_ID_HEADER, ResponseBody};
use crate::questions::{Entry, Question, Questions};

/// How far a probability distribution's total may fall from 1. The API
/// reports probabilities rounded to a few decimal places, so the total of a
/// valid answer drifts by a rounding error for each option.
pub const PROBABILITY_TOLERANCE: f64 = 0.05;

/// The probability that the answer to a Noul question is yes.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct NoulAnswer {
    /// The probability of yes, from 0 to 1.
    pub noul: f64,
    /// The option the estimator's own distribution named, when the door
    /// reports one.
    ///
    /// `noul` is the probability of yes and stays that even when a served
    /// calibration map has pulled it below one half: on a calibrated answer
    /// this field is what `noul` was measured on, so a reader that wants
    /// the estimator's pick reads it rather than deriving one from the
    /// number. When absent, a categorical reader falls back to yes at or
    /// above one half and no below. Absence does not prove that the door is
    /// uncalibrated; legacy responses carry no selected-answer provenance.
    #[serde(default)]
    pub selected: Option<String>,
}

/// The option a Choice question picked, with a probability for each option.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct ChoiceAnswer {
    /// The option the model picked.
    pub choice: String,
    /// How sharp the distribution is, as the API reports it.
    pub confidence: f64,
    /// A probability for each option, in the order the response sends them.
    pub probabilities: IndexMap<String, f64>,
}

/// Where a Score question placed the state, with the rubric it read.
#[derive(Debug, Clone, PartialEq, Deserialize)]
pub struct ScoreAnswer {
    /// The probability-weighted mean level, which falls between levels.
    /// A caller that needs a categorical level reads `selected`, or falls
    /// back to the argmax of `probabilities` when the answer lacks it.
    /// `docs/decision-models/2026-09-20-score-contract.md` states the rule.
    pub score: f64,
    /// How sharp the distribution is, as the API reports it.
    pub confidence: f64,
    /// The level the estimator's own distribution named, when the door
    /// reports one.
    ///
    /// A served calibration map rescales the selected level's probability
    /// without replacing the answer, and can leave a runner-up numerically
    /// larger in `probabilities`; this field is then the only place the
    /// estimator's pick survives the wire. When absent, a categorical reader
    /// falls back to the argmax of `probabilities`, with a tied maximum
    /// resolving to the highest level. Absence is not evidence that no
    /// calibration map was served.
    #[serde(default)]
    pub selected: Option<String>,
    /// The rubric, keyed by level.
    pub legend: BTreeMap<u32, Entry>,
    /// A probability for each level. The API leaves this out on some answers,
    /// and the field is then empty.
    #[serde(default)]
    pub probabilities: BTreeMap<u32, f64>,
}

/// One answer, of whichever type its question asked.
#[derive(Debug, Clone, PartialEq)]
pub enum Answer {
    /// The answer to a Noul question.
    Noul(NoulAnswer),
    /// The answer to a Choice question.
    Choice(ChoiceAnswer),
    /// The answer to a Score question.
    Score(ScoreAnswer),
}

impl Answer {
    /// The wire name of the answer's type.
    #[must_use]
    pub fn kind(&self) -> &'static str {
        match self {
            Self::Noul(_) => "noul",
            Self::Choice(_) => "choice",
            Self::Score(_) => "score",
        }
    }
}

/// What one request cost, as far as the API reports it. The API leaves a count
/// out on some responses.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Deserialize)]
pub struct Usage {
    /// Tokens the state and the questions took.
    #[serde(default)]
    pub input_tokens: Option<u64>,
    /// Tokens the answers took.
    #[serde(default)]
    pub output_tokens: Option<u64>,
}

/// One response as it arrived: its status, its headers, and its bytes.
///
/// The bytes are kept rather than a parsed body, so the order the API sent its
/// answers and its probabilities in survives decoding.
#[derive(Debug, Clone, PartialEq)]
pub struct RawResponse {
    /// The response status.
    pub status: u16,
    /// The response headers.
    pub headers: HeaderMap,
    /// The response body, as it arrived.
    pub bytes: Vec<u8>,
}

impl RawResponse {
    /// The body parsed as JSON when it parses, and as text when it does not.
    /// An empty body is `None`.
    #[must_use]
    pub fn body(&self) -> Option<ResponseBody> {
        crate::transport::parse_body(&self.bytes)
    }

    /// The body as text, with unreadable bytes replaced.
    #[must_use]
    pub fn text(&self) -> Cow<'_, str> {
        String::from_utf8_lossy(&self.bytes)
    }

    /// The request id, when the response carried one.
    #[must_use]
    pub fn request_id(&self) -> Option<&str> {
        self.headers
            .get(REQUEST_ID_HEADER)
            .and_then(|value| value.to_str().ok())
    }
}

/// The answers to one request, with the model that gave them and what they
/// cost.
#[derive(Debug, Clone)]
pub struct SystemOneResponse {
    /// The model the API answered with.
    pub model: String,
    /// Every answer the SDK could read, keyed by question id, in the order the
    /// response sent them.
    pub answers: IndexMap<String, Answer>,
    /// What the request cost.
    pub usage: Usage,
    raw: RawResponse,
}

impl SystemOneResponse {
    /// Read one response body.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ResponseValidation`] naming the first field the SDK
    /// cannot read.
    pub fn decode(raw: RawResponse) -> Result<Self> {
        // Serde reads a struct from a JSON array as well as from an object, and
        // a response is an object, so the first byte is checked here.
        if raw.bytes.iter().find(|byte| !byte.is_ascii_whitespace()) != Some(&b'{') {
            return Err(validation(&raw, "body".to_string()));
        }
        let wire: Wire = serde_json::from_slice(&raw.bytes)
            .map_err(|_| validation(&raw, blame_body(&raw.bytes)))?;
        let model = wire
            .model
            .ok_or_else(|| validation(&raw, "model".to_string()))?;
        let mut answers = IndexMap::with_capacity(wire.answers.len());
        for (id, body) in &wire.answers {
            if let Some(answer) = decode_answer(&raw, id, body)? {
                answers.insert(id.clone(), answer);
            }
        }
        Ok(Self {
            model,
            answers,
            usage: wire.usage.unwrap_or_default(),
            raw,
        })
    }

    /// Check the answers against the questions that were asked.
    ///
    /// Every question of a type this crate models needs an answer of that
    /// type, a Choice answer names one of its question's options, and a
    /// Score answer's levels fall within its question's rubric. An answer to
    /// a question that was not asked is left alone.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ResponseValidation`] naming the first answer that
    /// does not fit its question.
    pub fn validate_for(&self, questions: &Questions) -> Result<()> {
        let fail = |path: String| validation(&self.raw, path);
        for (id, question) in questions.iter() {
            let expected = match question {
                Question::Noul(_) => "noul",
                Question::Choice(_) => "choice",
                Question::Score(_) => "score",
                Question::Raw(_) => match question.kind() {
                    Some(kind @ ("noul" | "choice" | "score")) => kind,
                    _ => continue,
                },
            };
            let Some(answer) = self.answers.get(id) else {
                return Err(fail(format!("answers.{id}")));
            };
            if answer.kind() != expected {
                return Err(fail(format!("answers.{id}.type")));
            }
            match (answer, question) {
                (Answer::Choice(answer), Question::Choice(question))
                    if !question.criteria.is_empty() =>
                {
                    if !question.criteria.contains_key(&answer.choice) {
                        return Err(fail(format!("answers.{id}.choice")));
                    }
                    if let Some(option) = answer
                        .probabilities
                        .keys()
                        .find(|option| !question.criteria.contains_key(*option))
                    {
                        return Err(fail(format!("answers.{id}.probabilities.{option}")));
                    }
                }
                (Answer::Score(answer), Question::Score(question))
                    if !question.criteria.is_empty() =>
                {
                    let rubric = question.criteria.len();
                    let outside = |level: &u32| *level as usize >= rubric;
                    if let Some(level) = answer.legend.keys().find(|l| outside(l)) {
                        return Err(fail(format!("answers.{id}.legend.{level}")));
                    }
                    if let Some(level) = answer.probabilities.keys().find(|l| outside(l)) {
                        return Err(fail(format!("answers.{id}.probabilities.{level}")));
                    }
                    if answer.score > (rubric - 1) as f64 {
                        return Err(fail(format!("answers.{id}.score")));
                    }
                }
                _ => {}
            }
        }
        Ok(())
    }

    /// The response as it arrived.
    #[must_use]
    pub fn raw(&self) -> &RawResponse {
        &self.raw
    }

    /// The request id, when the response carried one. Quote it when you report
    /// a failure to TypeSafe.
    #[must_use]
    pub fn request_id(&self) -> Option<&str> {
        self.raw.request_id()
    }

    /// The Noul answer one question id holds.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] when no answer carries that id, and
    /// [`Error::AnswerType`] when the answer is of another type.
    pub fn noul(&self, id: &str) -> Result<&NoulAnswer> {
        match self.answer(id)? {
            Answer::Noul(answer) => Ok(answer),
            other => Err(mismatch(id, "noul", other)),
        }
    }

    /// The Choice answer one question id holds.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] when no answer carries that id, and
    /// [`Error::AnswerType`] when the answer is of another type.
    pub fn choice(&self, id: &str) -> Result<&ChoiceAnswer> {
        match self.answer(id)? {
            Answer::Choice(answer) => Ok(answer),
            other => Err(mismatch(id, "choice", other)),
        }
    }

    /// The Score answer one question id holds.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MissingAnswer`] when no answer carries that id, and
    /// [`Error::AnswerType`] when the answer is of another type.
    pub fn score(&self, id: &str) -> Result<&ScoreAnswer> {
        match self.answer(id)? {
            Answer::Score(answer) => Ok(answer),
            other => Err(mismatch(id, "score", other)),
        }
    }

    /// Every Noul answer with its question id, in order.
    pub fn nouls(&self) -> impl Iterator<Item = (&str, &NoulAnswer)> {
        self.answers.iter().filter_map(|(id, answer)| match answer {
            Answer::Noul(answer) => Some((id.as_str(), answer)),
            _ => None,
        })
    }

    /// Every Choice answer with its question id, in order.
    pub fn choices(&self) -> impl Iterator<Item = (&str, &ChoiceAnswer)> {
        self.answers.iter().filter_map(|(id, answer)| match answer {
            Answer::Choice(answer) => Some((id.as_str(), answer)),
            _ => None,
        })
    }

    /// Every Score answer with its question id, in order.
    pub fn scores(&self) -> impl Iterator<Item = (&str, &ScoreAnswer)> {
        self.answers.iter().filter_map(|(id, answer)| match answer {
            Answer::Score(answer) => Some((id.as_str(), answer)),
            _ => None,
        })
    }

    /// One answer of any type.
    fn answer(&self, id: &str) -> Result<&Answer> {
        self.answers
            .get(id)
            .ok_or_else(|| Error::MissingAnswer { id: id.to_string() })
    }
}

/// The response body, with each answer left as bytes so an unknown type is
/// skipped one answer at a time.
#[derive(Deserialize)]
struct Wire {
    #[serde(default)]
    model: Option<String>,
    #[serde(default)]
    usage: Option<Usage>,
    #[serde(default)]
    answers: IndexMap<String, Box<RawValue>>,
}

/// An answer's type, read before the answer itself.
#[derive(Deserialize)]
struct Tag {
    #[serde(default)]
    r#type: Option<String>,
}

/// One answer, or `None` when its type is one this crate does not model.
fn decode_answer(raw: &RawResponse, id: &str, body: &RawValue) -> Result<Option<Answer>> {
    let tag: Tag = serde_json::from_str(body.get())
        .map_err(|_| validation(raw, format!("answers.{id}.type")))?;
    let kind = tag
        .r#type
        .ok_or_else(|| validation(raw, format!("answers.{id}.type")))?;
    match kind.as_str() {
        "noul" => {
            let answer: NoulAnswer = read(raw, id, body, NOUL_FIELDS)?;
            if !probability(answer.noul) {
                return Err(validation(raw, format!("answers.{id}.noul")));
            }
            if answer
                .selected
                .as_deref()
                .is_some_and(|option| !matches!(option, "no" | "yes"))
            {
                return Err(validation(raw, format!("answers.{id}.selected")));
            }
            Ok(Some(Answer::Noul(answer)))
        }
        "choice" => {
            let answer: ChoiceAnswer = read(raw, id, body, CHOICE_FIELDS)?;
            if !probability(answer.confidence) {
                return Err(validation(raw, format!("answers.{id}.confidence")));
            }
            for (option, value) in &answer.probabilities {
                if !probability(*value) {
                    return Err(validation(
                        raw,
                        format!("answers.{id}.probabilities.{option}"),
                    ));
                }
            }
            if !answer.probabilities.contains_key(&answer.choice) {
                return Err(validation(raw, format!("answers.{id}.choice")));
            }
            if !has_unit_mass(answer.probabilities.values().copied()) {
                return Err(validation(raw, format!("answers.{id}.probabilities")));
            }
            Ok(Some(Answer::Choice(answer)))
        }
        "score" => {
            let answer: ScoreAnswer = read(raw, id, body, SCORE_FIELDS)?;
            check_score(raw, id, &answer)?;
            if let Some(selected) = &answer.selected {
                let valid = selected.parse::<u32>().ok().is_some_and(|level| {
                    level.to_string() == *selected && answer.probabilities.contains_key(&level)
                });
                if !valid {
                    return Err(validation(raw, format!("answers.{id}.selected")));
                }
            }
            Ok(Some(Answer::Score(answer)))
        }
        other => {
            // A newer API may answer with a type this crate does not model. The
            // rest of the response still reads, and the bytes stay on `raw()`.
            tracing::warn!(
                target: "jev",
                answer = id,
                answer_type = other,
                "skipping an answer of a type this client does not read"
            );
            Ok(None)
        }
    }
}

/// Whether a number is finite and between 0 and 1.
fn probability(value: f64) -> bool {
    (0.0..=1.0).contains(&value)
}

/// Whether probabilities total 1, within [`PROBABILITY_TOLERANCE`].
fn has_unit_mass(values: impl Iterator<Item = f64>) -> bool {
    (values.sum::<f64>() - 1.0).abs() <= PROBABILITY_TOLERANCE
}

/// The ranges a Score answer's numbers and levels must keep. The weighted
/// position stays within the rubric's lowest and highest level, and it is not
/// rounded to a level.
fn check_score(raw: &RawResponse, id: &str, answer: &ScoreAnswer) -> Result<()> {
    let fail = |field: String| validation(raw, format!("answers.{id}.{field}"));
    if !probability(answer.confidence) {
        return Err(fail("confidence".to_string()));
    }
    let levels: Vec<u32> = if answer.legend.is_empty() {
        answer.probabilities.keys().copied().collect()
    } else {
        answer.legend.keys().copied().collect()
    };
    if let Some((low, high)) = levels.first().zip(levels.last())
        && !(f64::from(*low)..=f64::from(*high)).contains(&answer.score)
    {
        return Err(fail("score".to_string()));
    }
    if !answer.score.is_finite() {
        return Err(fail("score".to_string()));
    }
    for (level, value) in &answer.probabilities {
        let outside = !answer.legend.is_empty() && !answer.legend.contains_key(level);
        if outside || !probability(*value) {
            return Err(fail(format!("probabilities.{level}")));
        }
    }
    if !answer.probabilities.is_empty() && !has_unit_mass(answer.probabilities.values().copied()) {
        return Err(fail("probabilities".to_string()));
    }
    if let Some(selected) = &answer.selected
        && !selected
            .parse::<u32>()
            .ok()
            .is_some_and(|level| answer.legend.is_empty() || answer.legend.contains_key(&level))
    {
        return Err(fail("selected".to_string()));
    }
    Ok(())
}

/// One answer of a known type, or the first field that stopped it.
fn read<T: for<'de> Deserialize<'de>>(
    raw: &RawResponse,
    id: &str,
    body: &RawValue,
    fields: &[Field],
) -> Result<T> {
    serde_json::from_str(body.get()).map_err(|_| {
        let path = match blame_field(body.get(), fields) {
            Some(field) => format!("answers.{id}.{field}"),
            None => format!("answers.{id}"),
        };
        validation(raw, path)
    })
}

/// One field of an answer: its name, the JSON shape it takes, and whether the
/// API may leave it out.
struct Field {
    name: &'static str,
    shape: Shape,
    required: bool,
}

/// The JSON shape a field takes on the wire.
enum Shape {
    Number,
    Text,
    Object,
}

const NOUL_FIELDS: &[Field] = &[
    Field {
        name: "noul",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "selected",
        shape: Shape::Text,
        required: false,
    },
];

const CHOICE_FIELDS: &[Field] = &[
    Field {
        name: "choice",
        shape: Shape::Text,
        required: true,
    },
    Field {
        name: "confidence",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "probabilities",
        shape: Shape::Object,
        required: true,
    },
];

const SCORE_FIELDS: &[Field] = &[
    Field {
        name: "score",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "confidence",
        shape: Shape::Number,
        required: true,
    },
    Field {
        name: "legend",
        shape: Shape::Object,
        required: true,
    },
    Field {
        name: "selected",
        shape: Shape::Text,
        required: false,
    },
    Field {
        name: "probabilities",
        shape: Shape::Object,
        required: false,
    },
];

/// The first field that is missing or the wrong shape, for the dotted path an
/// error names.
fn blame_field(body: &str, fields: &[Field]) -> Option<String> {
    let value: Value = serde_json::from_str(body).ok()?;
    for field in fields {
        match value.get(field.name) {
            None => {
                if field.required {
                    return Some(field.name.to_string());
                }
            }
            Some(found) => {
                let fits = match field.shape {
                    Shape::Number => found.is_number(),
                    Shape::Text => found.is_string(),
                    Shape::Object => found.is_object(),
                };
                if !fits {
                    return Some(field.name.to_string());
                }
                // A level map decodes only when every key is a level, and a
                // probability map only when every value is a number. The path
                // names the entry at fault, the way the Python SDK does.
                if matches!(field.name, "legend" | "probabilities")
                    && let Some(bad) = blame_entry(field.name, found)
                {
                    return Some(bad);
                }
            }
        }
    }
    None
}

/// The entry of a level map that does not decode: a key that is not a level
/// number, or for `probabilities` a value that is not a number.
fn blame_entry(field: &str, map: &Value) -> Option<String> {
    for (key, value) in map.as_object()? {
        if key.parse::<u32>().is_err() || (field == "probabilities" && !value.is_number()) {
            return Some(format!("{field}.{key}"));
        }
    }
    None
}

/// Which top-level field stopped the body from reading at all.
fn blame_body(bytes: &[u8]) -> String {
    let Ok(value) = serde_json::from_slice::<Value>(bytes) else {
        return "body".to_string();
    };
    let Some(object) = value.as_object() else {
        return "body".to_string();
    };
    if object.get("model").is_some_and(|model| !model.is_string()) {
        return "model".to_string();
    }
    match object.get("answers") {
        Some(answers) if !answers.is_object() => "answers".to_string(),
        _ => match object.get("usage") {
            Some(usage) if !usage.is_object() && !usage.is_null() => "usage".to_string(),
            _ => "body".to_string(),
        },
    }
}

/// The error a body the SDK cannot read raises.
fn validation(raw: &RawResponse, field_path: String) -> Error {
    Error::ResponseValidation {
        status: raw.status,
        field_path,
        body: raw.body().map(Box::new),
        request_id: raw.request_id().map(str::to_string),
    }
}

/// The error a typed accessor raises when the id holds another type.
fn mismatch(id: &str, expected: &'static str, found: &Answer) -> Error {
    Error::AnswerType {
        id: id.to_string(),
        expected,
        found: found.kind(),
    }
}

//! The client, the request it sends, and the loop that retries one.
//!
//! One attempt is one HTTP round trip under one timeout. A failure the policy
//! retries waits and runs again, and the wait is the policy's own unless the
//! server asked for a longer one. Every attempt and every retry is one `info`
//! line under the `jev` target.

use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{Duration, Instant};

use reqwest::header::{HeaderMap, HeaderValue};
use reqwest::{Method, StatusCode};
use serde_json::{Map, Value};

use crate::Result;
use crate::answers::{RawResponse, SystemOneResponse};
use crate::config::{ApiKey, Config};
use crate::error::{ApiError, Error, REQUEST_ID_HEADER};
use crate::models::{ListOptions, Models};
use crate::questions::{Entry, Questions};
use crate::retry::{RETRY_COUNT_HEADER, RetryPolicy};
use crate::transport;

/// The route that answers questions.
const SYSTEM_ONE_PATH: &str = "/v1/systemone";

/// The route that lists models.
const MODELS_PATH: &str = "/v1/models";

/// One state, the questions to ask about it, and what this call overrides.
///
/// ```
/// use jev::{Noul, Questions, SystemOneRequest};
///
/// let request = SystemOneRequest::new(
///     "I was charged twice for one order.",
///     Questions::new().with("billing", Noul::new("Is this about a charge?")),
/// )
/// .model("jev-latest");
/// ```
#[derive(Debug, Clone)]
pub struct SystemOneRequest {
    /// The state every question reads. One state, not a batch.
    pub state: Entry,
    /// The questions to ask.
    pub questions: Questions,
    /// The model to ask, or the client's default.
    pub model: Option<String>,
    /// The policy to retry this call by, or the client's own.
    pub retry: Option<RetryPolicy>,
    /// The timeout each attempt of this call takes, or the client's own.
    pub timeout: Option<Duration>,
    /// Headers this call adds.
    pub headers: HeaderMap,
    /// Fields to merge into the body last, for a field the API takes and this
    /// crate does not model. A field here replaces one the SDK wrote.
    pub extra_body: Map<String, Value>,
}

impl SystemOneRequest {
    /// Ask questions about one state.
    #[must_use]
    pub fn new<E: Into<Entry>>(state: E, questions: Questions) -> Self {
        Self {
            state: state.into(),
            questions,
            model: None,
            retry: None,
            timeout: None,
            headers: HeaderMap::new(),
            extra_body: Map::new(),
        }
    }

    /// Ask another model than the client's default.
    #[must_use]
    pub fn model<M: Into<String>>(mut self, model: M) -> Self {
        self.model = Some(model.into());
        self
    }

    /// Retry this call by another policy.
    ///
    /// The policy replaces the client's. Build one over the client's own with
    /// struct update syntax when you mean to change one field:
    /// `RetryPolicy { max_retries: 0, ..client.retry().clone() }`.
    #[must_use]
    pub fn retry(mut self, retry: RetryPolicy) -> Self {
        self.retry = Some(retry);
        self
    }

    /// Give each attempt of this call another timeout.
    #[must_use]
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }

    /// Add headers to this call.
    #[must_use]
    pub fn headers(mut self, headers: HeaderMap) -> Self {
        self.headers = headers;
        self
    }

    /// Merge fields into the body last.
    #[must_use]
    pub fn extra_body(mut self, extra: Map<String, Value>) -> Self {
        self.extra_body = extra;
        self
    }

    /// The body one call of this request sends, with `default_model` where
    /// the request names no model of its own. Nothing goes out: a caller
    /// that records the exchange reads it.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Question`] when the question set fails its checks and
    /// [`Error::Config`] when the questions do not serialize.
    pub fn body(&self, default_model: &str) -> Result<Map<String, Value>> {
        self.questions.validate()?;
        let mut body = Map::new();
        body.insert("state".to_string(), self.state.to_value());
        body.insert(
            "model".to_string(),
            Value::String(
                self.model
                    .clone()
                    .unwrap_or_else(|| default_model.to_string()),
            ),
        );
        body.insert(
            "questions".to_string(),
            serde_json::to_value(&self.questions)
                .map_err(|error| Error::Config(format!("the questions are not JSON: {error}")))?,
        );
        for (name, value) in &self.extra_body {
            body.insert(name.clone(), value.clone());
        }
        Ok(body)
    }
}

/// A client for TypeSafe's System One API.
///
/// The client is cheap to clone and holds one HTTP connection pool, so build
/// one and share it.
#[derive(Debug, Clone)]
pub struct Client {
    inner: Arc<Inner>,
}

/// What every request reads, behind one allocation.
#[derive(Debug)]
struct Inner {
    api_key: ApiKey,
    base_url: String,
    default_model: String,
    timeout: Duration,
    retry: RetryPolicy,
    default_headers: HeaderMap,
    http: reqwest::Client,
    requests: AtomicU64,
}

impl Client {
    /// Build a client from settings, filling in what they leave out from the
    /// environment and the defaults.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Config`] when no key is set, the base URL is not an
    /// http or https URL, the timeout is zero, or a retry field is out of
    /// range.
    pub fn new(config: Config) -> Result<Self> {
        let resolved = config.resolve()?;
        Ok(Self {
            inner: Arc::new(Inner {
                api_key: resolved.api_key,
                base_url: resolved.base_url,
                default_model: resolved.default_model,
                timeout: resolved.timeout,
                retry: resolved.retry,
                default_headers: resolved.default_headers,
                http: resolved.http,
                requests: AtomicU64::new(0),
            }),
        })
    }

    /// Build a client from the environment and the defaults alone.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::new`].
    pub fn from_env() -> Result<Self> {
        Self::new(Config::new())
    }

    /// The API root, with trailing slashes dropped.
    #[must_use]
    pub fn base_url(&self) -> &str {
        &self.inner.base_url
    }

    /// The model a request that names none asks.
    #[must_use]
    pub fn default_model(&self) -> &str {
        &self.inner.default_model
    }

    /// How long one attempt may take.
    #[must_use]
    pub fn timeout(&self) -> Duration {
        self.inner.timeout
    }

    /// What the client retries and how long it waits.
    #[must_use]
    pub fn retry(&self) -> &RetryPolicy {
        &self.inner.retry
    }

    /// The headers every request carries, before the ones the API reads to
    /// identify it.
    #[must_use]
    pub fn default_headers(&self) -> &HeaderMap {
        &self.inner.default_headers
    }

    /// The models the account can ask.
    #[must_use]
    pub fn models(&self) -> Models<'_> {
        Models::new(self)
    }

    /// Ask questions about one state and read the answers.
    ///
    /// The policy's `budget`, when set, is a monotonic deadline for the whole
    /// call, including the first attempt, the body read, every wait, and
    /// every retry; each attempt's timeout is capped at the time the call has
    /// left.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Question`] when the question set fails its checks,
    /// before any request. Returns [`Error::Api`], [`Error::Connection`], or
    /// [`Error::Timeout`] when the call fails after its retries or runs out
    /// of budget, and [`Error::ResponseValidation`] when the answers do not
    /// read or fall outside their ranges. [`Client::system_one_raw`] hands
    /// the response back unread.
    pub async fn system_one(&self, request: SystemOneRequest) -> Result<SystemOneResponse> {
        let prepared = self.prepare_system_one(&request)?;
        let raw = self.send_read(&prepared).await?;
        SystemOneResponse::decode(raw)
    }

    /// Ask questions about one state and read the answers, checking them
    /// against the questions asked.
    ///
    /// This is [`Client::system_one`] followed by
    /// [`SystemOneResponse::validate_for`]: a missing answer, an answer of
    /// the wrong type, or an option the question does not offer fails the
    /// call. [`Client::system_one`] keeps the compatibility behavior of
    /// checking only each answer on its own.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one`], and
    /// [`Error::ResponseValidation`] when an answer does not fit its question.
    pub async fn system_one_checked(&self, request: SystemOneRequest) -> Result<SystemOneResponse> {
        let prepared = self.prepare_system_one(&request)?;
        let raw = self.send_read(&prepared).await?;
        let response = SystemOneResponse::decode(raw)?;
        response.validate_for(&request.questions)?;
        Ok(response)
    }

    /// Ask questions about one state and hand back the response unread, for a
    /// caller that wants the bytes.
    ///
    /// The call is bounded the way [`Client::system_one`] is, and the
    /// returned response's body stays under the same deadline: the attempt's
    /// timeout — capped by the remaining budget — still applies while the
    /// caller reads the body, so a read past the deadline fails rather than
    /// outliving the call's budget.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one`], other than
    /// [`Error::ResponseValidation`].
    pub async fn system_one_raw(&self, request: SystemOneRequest) -> Result<reqwest::Response> {
        let prepared = self.prepare_system_one(&request)?;
        self.send(&prepared).await
    }

    /// Everything one `POST /v1/systemone` call sends, before its first
    /// attempt.
    fn prepare_system_one(&self, request: &SystemOneRequest) -> Result<Prepared> {
        let body = request.body(&self.inner.default_model)?;
        let encoded = serde_json::to_vec(&Value::Object(body))
            .map_err(|error| Error::Config(format!("the request body is not JSON: {error}")))?;
        self.prepare(
            Method::POST,
            SYSTEM_ONE_PATH,
            Some(encoded),
            &request.headers,
            request.timeout,
            request.retry.clone(),
        )
    }

    /// One `GET /v1/models`, read into bytes.
    pub(crate) async fn list_models(&self, options: ListOptions) -> Result<RawResponse> {
        let prepared = self.prepare(
            Method::GET,
            MODELS_PATH,
            None,
            &options.headers,
            options.timeout,
            options.retry,
        )?;
        self.send_read(&prepared).await
    }

    /// Everything one call sends, before its first attempt.
    fn prepare(
        &self,
        method: Method,
        path: &'static str,
        body: Option<Vec<u8>>,
        headers: &HeaderMap,
        timeout: Option<Duration>,
        retry: Option<RetryPolicy>,
    ) -> Result<Prepared> {
        let timeout = timeout.unwrap_or(self.inner.timeout);
        if timeout.is_zero() {
            return Err(Error::Config(
                "`timeout` must be a positive duration".to_string(),
            ));
        }
        let retry = match retry {
            Some(retry) => {
                retry.validate()?;
                retry
            }
            None => self.inner.retry.clone(),
        };
        let headers = transport::headers(
            &self.inner.default_headers,
            headers,
            &self.inner.api_key,
            body.is_some(),
        )?;
        Ok(Prepared {
            tag: self.inner.requests.fetch_add(1, Ordering::Relaxed) + 1,
            url: format!("{}{path}", self.inner.base_url),
            endpoint: format!("{method} {}{path}", endpoint_of(&self.inner.base_url)),
            method,
            body,
            headers,
            timeout,
            retry,
        })
    }

    /// One call: the first attempt and every retry the policy allows.
    async fn send(&self, prepared: &Prepared) -> Result<reqwest::Response> {
        self.send_with(prepared, Client::attempt).await
    }

    /// One call whose body is read inside each attempt, so a body that stalls
    /// or breaks is retried the way both official SDKs retry one.
    async fn send_read(&self, prepared: &Prepared) -> Result<RawResponse> {
        self.send_with(prepared, Client::attempt_read).await
    }

    /// The retry loop both send paths share.
    ///
    /// `retry.budget`, when set, is a monotonic deadline for the whole call,
    /// measured from the first attempt's dispatch: it covers the first
    /// attempt, every retry, every wait between them, and the body a read
    /// path consumes inside its attempt. Each attempt's timeout is the
    /// smaller of the call's own timeout and the time the call has left, so
    /// a reply that arrives after the deadline cannot succeed, and a retry
    /// whose wait would reach the deadline never runs.
    async fn send_with<T>(
        &self,
        prepared: &Prepared,
        attempt: impl AsyncFn(&Client, &Prepared, u32, Duration) -> std::result::Result<T, Failed>,
    ) -> Result<T> {
        let started = Instant::now();
        // A budget too large to name on this clock is no deadline at all.
        let deadline = prepared
            .retry
            .budget
            .and_then(|budget| started.checked_add(budget));
        let mut attempt_no: u32 = 0;
        let mut last: Option<Failed> = None;
        loop {
            let timeout = match deadline {
                Some(deadline) => {
                    let remaining = deadline.saturating_duration_since(Instant::now());
                    if remaining.is_zero() {
                        // The call's time is spent. The failure already held
                        // is the answer; a call that never ran an attempt
                        // reports the bound it ran out of.
                        return Err(match last {
                            Some(failed) => failed.error,
                            None => Error::Timeout {
                                timeout: prepared
                                    .retry
                                    .budget
                                    .map_or(prepared.timeout, |b| prepared.timeout.min(b)),
                            },
                        });
                    }
                    prepared.timeout.min(remaining)
                }
                None => prepared.timeout,
            };
            match attempt(self, prepared, attempt_no, timeout).await {
                Ok(done) => return Ok(done),
                Err(failed) => {
                    let retries_left = prepared.retry.max_retries.saturating_sub(attempt_no);
                    if retries_left == 0 || !prepared.retry.retries_error(&failed.error) {
                        return Err(failed.error);
                    }
                    let delay = prepared.retry.delay(attempt_no, failed.headers.as_ref());
                    if let Some(budget) = prepared.retry.budget
                        && started.elapsed().saturating_add(delay) >= budget
                    {
                        tracing::info!(
                            target: "jev",
                            request = prepared.tag,
                            budget_ms = budget.as_millis(),
                            "the retry budget is spent; returning the last failure"
                        );
                        return Err(failed.error);
                    }
                    tracing::info!(
                        target: "jev",
                        request = prepared.tag,
                        retry = attempt_no + 1,
                        of = prepared.retry.max_retries,
                        delay_ms = delay.as_millis(),
                        reason = %failed.error,
                        "waiting before the next attempt"
                    );
                    tokio::time::sleep(delay).await;
                    attempt_no += 1;
                    last = Some(failed);
                }
            }
        }
    }

    /// One HTTP round trip under one timeout, with the body read inside the
    /// timeout as well. A body that breaks is a connection failure the policy
    /// can retry.
    async fn attempt_read(
        &self,
        prepared: &Prepared,
        attempt: u32,
        timeout: Duration,
    ) -> std::result::Result<RawResponse, Failed> {
        let response = self.attempt(prepared, attempt, timeout).await?;
        let status = response.status().as_u16();
        let headers = response.headers().clone();
        match response.bytes().await {
            Ok(bytes) => Ok(RawResponse {
                status,
                headers,
                bytes: bytes.to_vec(),
            }),
            Err(source) => {
                // A body that stalls past the timeout is a timeout, the way
                // the Python SDK names a read timeout.
                let error = if source.is_timeout() {
                    Error::Timeout { timeout }
                } else {
                    Error::connection(source)
                };
                Err(Failed {
                    error,
                    headers: Some(headers),
                })
            }
        }
    }

    /// One HTTP round trip under one timeout: the smaller of the call's own
    /// and the time a budget leaves it. The reqwest timeout holds through the
    /// body read, so a body that stalls past the deadline ends the attempt
    /// the same way a stalled head does.
    async fn attempt(
        &self,
        prepared: &Prepared,
        attempt: u32,
        timeout: Duration,
    ) -> std::result::Result<reqwest::Response, Failed> {
        let mut headers = prepared.headers.clone();
        if attempt > 0 {
            headers.insert(RETRY_COUNT_HEADER, HeaderValue::from(attempt));
        }
        tracing::debug!(
            target: "jev",
            request = prepared.tag,
            method = %prepared.method,
            url = %prepared.url,
            headers = %transport::redact(&headers),
            body = %prepared.body_text(),
            "sending an attempt"
        );
        let mut builder = self
            .inner
            .http
            .request(prepared.method.clone(), &prepared.url)
            .headers(headers)
            .timeout(timeout);
        if let Some(body) = prepared.body.clone() {
            builder = builder.body(body);
        }
        let began = Instant::now();
        let response = match builder.send().await {
            Ok(response) => response,
            Err(error) => {
                let timed_out = error.is_timeout();
                let failure = if timed_out {
                    Error::Timeout { timeout }
                } else {
                    Error::connection(error)
                };
                tracing::info!(
                    target: "jev",
                    request = prepared.tag,
                    method = %prepared.method,
                    url = %prepared.url,
                    elapsed_ms = began.elapsed().as_millis(),
                    reason = %failure,
                    "the attempt did not reach the API"
                );
                return Err(Failed {
                    error: failure,
                    headers: None,
                });
            }
        };
        let status = response.status();
        tracing::info!(
            target: "jev",
            request = prepared.tag,
            method = %prepared.method,
            url = %prepared.url,
            status = status.as_u16(),
            elapsed_ms = began.elapsed().as_millis(),
            request_id = request_id(response.headers()).unwrap_or("-"),
            "the API answered"
        );
        if status.is_success() {
            return Ok(response);
        }
        Err(self.failure(prepared, status, response).await)
    }

    /// The error one failed response raises, with its body read.
    async fn failure(
        &self,
        prepared: &Prepared,
        status: StatusCode,
        response: reqwest::Response,
    ) -> Failed {
        let headers = response.headers().clone();
        let bytes = response
            .bytes()
            .await
            .map(|bytes| bytes.to_vec())
            .unwrap_or_default();
        let body = transport::parse_body(&bytes);
        tracing::debug!(
            target: "jev",
            request = prepared.tag,
            status = status.as_u16(),
            headers = %transport::redact(&headers),
            body = %String::from_utf8_lossy(&bytes),
            "the failed response carried this body"
        );
        Failed {
            error: Error::from(ApiError::new(
                prepared.endpoint.clone(),
                status.as_u16(),
                headers.clone(),
                body,
            )),
            headers: Some(headers),
        }
    }
}

/// One attempt that failed, with the response headers when there was a
/// response, so the retry can honor a server delay.
struct Failed {
    error: Error,
    headers: Option<HeaderMap>,
}

/// Everything one call sends, reused by every attempt.
struct Prepared {
    tag: u64,
    method: Method,
    url: String,
    endpoint: String,
    body: Option<Vec<u8>>,
    headers: HeaderMap,
    timeout: Duration,
    retry: RetryPolicy,
}

impl Prepared {
    /// The body as text for a `debug` line. Bodies are logged as they are sent,
    /// the way both official SDKs log them.
    fn body_text(&self) -> String {
        match self.body.as_deref() {
            Some(bytes) => String::from_utf8_lossy(bytes).into_owned(),
            None => String::new(),
        }
    }
}

impl RawResponse {
    /// Read one response into its status, its headers, and its bytes.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Connection`] when the body does not arrive.
    pub async fn read(response: reqwest::Response) -> Result<Self> {
        let status = response.status().as_u16();
        let headers = response.headers().clone();
        let bytes = response.bytes().await.map_err(Error::connection)?.to_vec();
        Ok(Self {
            status,
            headers,
            bytes,
        })
    }
}

/// The base URL as an error's endpoint names it: the credentials, the query,
/// and the fragment dropped, the way the Python SDK writes a request's URL.
fn endpoint_of(base_url: &str) -> String {
    let mut parsed = match url::Url::parse(base_url) {
        Ok(parsed) => parsed,
        Err(_) => return base_url.to_string(),
    };
    let _ = parsed.set_username("");
    let _ = parsed.set_password(None);
    parsed.set_query(None);
    parsed.set_fragment(None);
    parsed.to_string().trim_end_matches('/').to_string()
}

/// The request id one response carries.
fn request_id(headers: &HeaderMap) -> Option<&str> {
    headers
        .get(REQUEST_ID_HEADER)
        .and_then(|value| value.to_str().ok())
}

/// A client for a caller that runs no `tokio` runtime of its own.
///
/// Each call runs on a runtime this client owns. Do not call it from inside a
/// runtime; use [`Client`] there.
#[cfg(feature = "blocking")]
#[derive(Debug)]
pub struct BlockingClient {
    client: Client,
    runtime: tokio::runtime::Runtime,
}

#[cfg(feature = "blocking")]
impl BlockingClient {
    /// Build a blocking client from settings.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::new`], and [`Error::Config`] when
    /// the runtime does not start.
    pub fn new(config: Config) -> Result<Self> {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .map_err(|error| Error::Config(format!("the runtime did not start: {error}")))?;
        Ok(Self {
            client: Client::new(config)?,
            runtime,
        })
    }

    /// Build a blocking client from the environment and the defaults alone.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`BlockingClient::new`].
    pub fn from_env() -> Result<Self> {
        Self::new(Config::new())
    }

    /// The async client underneath.
    #[must_use]
    pub fn client(&self) -> &Client {
        &self.client
    }

    /// Ask questions about one state and read the answers.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one`].
    pub fn system_one(&self, request: SystemOneRequest) -> Result<SystemOneResponse> {
        self.runtime.block_on(self.client.system_one(request))
    }

    /// Ask questions and check the answers against them.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one_checked`].
    pub fn system_one_checked(&self, request: SystemOneRequest) -> Result<SystemOneResponse> {
        self.runtime
            .block_on(self.client.system_one_checked(request))
    }

    /// List the models the account can ask.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`crate::Models::list`].
    pub fn list_models(&self, options: ListOptions) -> Result<Vec<crate::ModelCard>> {
        self.runtime.block_on(self.client.models().list(options))
    }
}

//! The three question types, the state and criteria they carry, and the checks
//! that run before a request leaves.
//!
//! A question asks one narrow judgment. A Noul asks whether something is true,
//! a Choice picks one of named options, and a Score places the state on an
//! ordered rubric. Every question in one request reads the same state and is
//! answered on its own.

use indexmap::IndexMap;
use serde::ser::{SerializeMap, SerializeStruct};
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use serde_json::{Map, Value};

use crate::Result;
use crate::error::Error;

/// The most options a Choice question takes.
const MAX_CHOICE_OPTIONS: usize = 255;

/// The fewest levels a Score question takes.
const MIN_SCORE_LEVELS: usize = 2;

/// The most levels a Score question takes.
const MAX_SCORE_LEVELS: usize = 10;

/// Text, a JSON object, a JSON array, or nothing.
///
/// State, instructions, and every criterion take one of these four shapes. A
/// number or a boolean becomes its text form, because the API reads none of the
/// four as a bare scalar.
#[derive(Debug, Clone, PartialEq, Default)]
pub enum Entry {
    /// Text.
    Text(String),
    /// A JSON object.
    Object(Map<String, Value>),
    /// A JSON array.
    Array(Vec<Value>),
    /// Nothing, which leaves the field undescribed.
    #[default]
    Null,
}

impl Entry {
    /// Build an entry from anything that serializes to JSON.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Config`] when the value does not serialize.
    pub fn json<T: Serialize>(value: &T) -> Result<Self> {
        let value = serde_json::to_value(value)
            .map_err(|error| Error::Config(format!("the value is not JSON: {error}")))?;
        Ok(Self::from(value))
    }

    /// The entry as a JSON value.
    #[must_use]
    pub fn to_value(&self) -> Value {
        match self {
            Self::Text(text) => Value::String(text.clone()),
            Self::Object(map) => Value::Object(map.clone()),
            Self::Array(items) => Value::Array(items.clone()),
            Self::Null => Value::Null,
        }
    }

    /// Whether the entry describes nothing.
    #[must_use]
    pub fn is_null(&self) -> bool {
        matches!(self, Self::Null)
    }
}

impl From<&str> for Entry {
    fn from(text: &str) -> Self {
        Self::Text(text.to_string())
    }
}

impl From<String> for Entry {
    fn from(text: String) -> Self {
        Self::Text(text)
    }
}

impl From<Map<String, Value>> for Entry {
    fn from(map: Map<String, Value>) -> Self {
        Self::Object(map)
    }
}

impl From<Vec<Value>> for Entry {
    fn from(items: Vec<Value>) -> Self {
        Self::Array(items)
    }
}

impl From<Value> for Entry {
    fn from(value: Value) -> Self {
        match value {
            Value::String(text) => Self::Text(text),
            Value::Object(map) => Self::Object(map),
            Value::Array(items) => Self::Array(items),
            Value::Null => Self::Null,
            other => Self::Text(other.to_string()),
        }
    }
}

impl Serialize for Entry {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        self.to_value().serialize(serializer)
    }
}

impl<'de> Deserialize<'de> for Entry {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> std::result::Result<Self, D::Error> {
        Value::deserialize(deserializer).map(Self::from)
    }
}

/// What a yes and a no mean, for a Noul question that reads better with the two
/// outcomes described.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct NoulCriteria {
    /// What a yes means.
    pub r#true: Option<Entry>,
    /// What a no means.
    pub r#false: Option<Entry>,
}

impl NoulCriteria {
    /// Criteria that describe neither outcome.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Describe the yes outcome.
    #[must_use]
    pub fn when_true<E: Into<Entry>>(mut self, description: E) -> Self {
        self.r#true = Some(description.into());
        self
    }

    /// Describe the no outcome.
    #[must_use]
    pub fn when_false<E: Into<Entry>>(mut self, description: E) -> Self {
        self.r#false = Some(description.into());
        self
    }
}

impl Serialize for NoulCriteria {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        let mut map = serializer.serialize_map(None)?;
        if let Some(entry) = self.r#true.as_ref() {
            map.serialize_entry("true", entry)?;
        }
        if let Some(entry) = self.r#false.as_ref() {
            map.serialize_entry("false", entry)?;
        }
        map.end()
    }
}

/// A question that asks whether something is true. The answer is one
/// probability of yes.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Noul {
    /// The judgment to make.
    pub instructions: Option<Entry>,
    /// What a yes and a no mean.
    pub criteria: Option<NoulCriteria>,
}

impl Noul {
    /// Ask a judgment with no outcome descriptions.
    #[must_use]
    pub fn new<E: Into<Entry>>(instructions: E) -> Self {
        Self {
            instructions: Some(instructions.into()),
            criteria: None,
        }
    }

    /// Ask a judgment and describe its two outcomes.
    #[must_use]
    pub fn with_criteria<E: Into<Entry>>(instructions: E, criteria: NoulCriteria) -> Self {
        Self {
            instructions: Some(instructions.into()),
            criteria: Some(criteria),
        }
    }
}

impl Serialize for Noul {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        let fields =
            1 + usize::from(self.instructions.is_some()) + usize::from(self.criteria.is_some());
        let mut state = serializer.serialize_struct("Noul", fields)?;
        state.serialize_field("type", "noul")?;
        if let Some(instructions) = self.instructions.as_ref() {
            state.serialize_field("instructions", instructions)?;
        }
        if let Some(criteria) = self.criteria.as_ref() {
            state.serialize_field("criteria", criteria)?;
        }
        state.end()
    }
}

/// A question that picks one of named options. The answer names the option and
/// carries a probability for each one.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Choice {
    /// The judgment to make.
    pub instructions: Option<Entry>,
    /// The options, in the order the request sends them.
    pub criteria: IndexMap<String, Option<Entry>>,
}

impl Choice {
    /// Ask a judgment over named options.
    #[must_use]
    pub fn new<E: Into<Entry>>(instructions: E, criteria: IndexMap<String, Option<Entry>>) -> Self {
        Self {
            instructions: Some(instructions.into()),
            criteria,
        }
    }

    /// Add one option, keeping the order the calls are made in.
    #[must_use]
    pub fn option<N: Into<String>, E: Into<Entry>>(mut self, name: N, description: E) -> Self {
        self.criteria.insert(name.into(), Some(description.into()));
        self
    }

    /// Add one option with no description.
    #[must_use]
    pub fn bare_option<N: Into<String>>(mut self, name: N) -> Self {
        self.criteria.insert(name.into(), None);
        self
    }
}

impl Serialize for Choice {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        let fields = 2 + usize::from(self.instructions.is_some());
        let mut state = serializer.serialize_struct("Choice", fields)?;
        state.serialize_field("type", "choice")?;
        if let Some(instructions) = self.instructions.as_ref() {
            state.serialize_field("instructions", instructions)?;
        }
        state.serialize_field("criteria", &self.criteria)?;
        state.end()
    }
}

/// A question that places the state on an ordered rubric. Level zero is the
/// first entry of `criteria`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Score {
    /// The judgment to make.
    pub instructions: Option<Entry>,
    /// The levels, in order from zero.
    pub criteria: Vec<Option<Entry>>,
}

impl Score {
    /// Ask a judgment over an ordered rubric.
    #[must_use]
    pub fn new<E: Into<Entry>>(instructions: E, criteria: Vec<Option<Entry>>) -> Self {
        Self {
            instructions: Some(instructions.into()),
            criteria,
        }
    }

    /// Add one level after the levels already named.
    #[must_use]
    pub fn level<E: Into<Entry>>(mut self, description: E) -> Self {
        self.criteria.push(Some(description.into()));
        self
    }
}

impl Serialize for Score {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        let fields = 2 + usize::from(self.instructions.is_some());
        let mut state = serializer.serialize_struct("Score", fields)?;
        state.serialize_field("type", "score")?;
        if let Some(instructions) = self.instructions.as_ref() {
            state.serialize_field("instructions", instructions)?;
        }
        state.serialize_field("criteria", &self.criteria)?;
        state.end()
    }
}

/// One question of any type.
///
/// [`Question::Raw`] carries a body the SDK does not model, for a field the API
/// adds before this crate does.
#[derive(Debug, Clone, PartialEq)]
pub enum Question {
    /// A question that asks whether something is true.
    Noul(Noul),
    /// A question that picks one of named options.
    Choice(Choice),
    /// A question that places the state on an ordered rubric.
    Score(Score),
    /// A question written out as JSON, sent as it stands.
    Raw(Value),
}

impl Question {
    /// The wire name of the question's type, or the `type` a raw question
    /// carries.
    #[must_use]
    pub fn kind(&self) -> Option<&str> {
        match self {
            Self::Noul(_) => Some("noul"),
            Self::Choice(_) => Some("choice"),
            Self::Score(_) => Some("score"),
            Self::Raw(value) => value.get("type").and_then(Value::as_str),
        }
    }
}

impl From<Noul> for Question {
    fn from(question: Noul) -> Self {
        Self::Noul(question)
    }
}

impl From<Choice> for Question {
    fn from(question: Choice) -> Self {
        Self::Choice(question)
    }
}

impl From<Score> for Question {
    fn from(question: Score) -> Self {
        Self::Score(question)
    }
}

impl From<Value> for Question {
    fn from(question: Value) -> Self {
        Self::Raw(question)
    }
}

impl Serialize for Question {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        match self {
            Self::Noul(question) => question.serialize(serializer),
            Self::Choice(question) => question.serialize(serializer),
            Self::Score(question) => question.serialize(serializer),
            Self::Raw(question) => question.serialize(serializer),
        }
    }
}

/// The questions one request asks, in the order they were added.
///
/// ```
/// use jev::{Noul, Questions, Score};
///
/// let questions = Questions::new()
///     .with("refund", Noul::new("Does the customer ask for money back?"))
///     .with(
///         "severity",
///         Score::new("How severe is the issue?", Vec::new())
///             .level("Cosmetic")
///             .level("Blocking"),
///     );
/// assert_eq!(questions.len(), 2);
/// assert!(questions.validate().is_ok());
/// ```
#[derive(Debug, Clone, PartialEq, Default)]
pub struct Questions(IndexMap<String, Question>);

impl Questions {
    /// An empty set. A request needs at least one question.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Add one question, keeping the order the calls are made in.
    #[must_use]
    pub fn with<I: Into<String>, Q: Into<Question>>(mut self, id: I, question: Q) -> Self {
        self.0.insert(id.into(), question.into());
        self
    }

    /// Add one question, returning the question that id already held.
    pub fn insert<I: Into<String>, Q: Into<Question>>(
        &mut self,
        id: I,
        question: Q,
    ) -> Option<Question> {
        self.0.insert(id.into(), question.into())
    }

    /// The question one id holds.
    #[must_use]
    pub fn get(&self, id: &str) -> Option<&Question> {
        self.0.get(id)
    }

    /// How many questions the set holds.
    #[must_use]
    pub fn len(&self) -> usize {
        self.0.len()
    }

    /// Whether the set holds no question.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    /// Every question with its id, in order.
    pub fn iter(&self) -> impl Iterator<Item = (&str, &Question)> {
        self.0.iter().map(|(id, question)| (id.as_str(), question))
    }

    /// Check the set the way both official SDKs check theirs, and the two
    /// limits the API documents.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Question`] when the set is empty, a Score names fewer
    /// than two or more than ten levels, or a Choice names more than 255
    /// options. The error names the question at fault.
    pub fn validate(&self) -> Result<()> {
        if self.0.is_empty() {
            return Err(Error::Question {
                id: String::new(),
                message: "a request asks at least one question".to_string(),
            });
        }
        for (id, question) in self.iter() {
            match question {
                Question::Score(score) => check_score(id, score.criteria.len())?,
                Question::Choice(choice) => check_choice(id, choice.criteria.len())?,
                Question::Noul(_) => {}
                Question::Raw(value) => check_raw(id, value)?,
            }
        }
        Ok(())
    }
}

impl From<IndexMap<String, Question>> for Questions {
    fn from(questions: IndexMap<String, Question>) -> Self {
        Self(questions)
    }
}

impl<K: Into<String>, Q: Into<Question>> FromIterator<(K, Q)> for Questions {
    fn from_iter<T: IntoIterator<Item = (K, Q)>>(items: T) -> Self {
        Self(
            items
                .into_iter()
                .map(|(id, question)| (id.into(), question.into()))
                .collect(),
        )
    }
}

impl Serialize for Questions {
    fn serialize<S: Serializer>(&self, serializer: S) -> std::result::Result<S::Ok, S::Error> {
        self.0.serialize(serializer)
    }
}

/// A Score question names an ordered rubric of two to ten levels.
fn check_score(id: &str, levels: usize) -> Result<()> {
    if levels < MIN_SCORE_LEVELS {
        return Err(Error::Question {
            id: id.to_string(),
            message: format!(
                "a Score question names at least {MIN_SCORE_LEVELS} levels, and this one names {levels}"
            ),
        });
    }
    if levels > MAX_SCORE_LEVELS {
        return Err(Error::Question {
            id: id.to_string(),
            message: format!(
                "a Score question names at most {MAX_SCORE_LEVELS} levels, and this one names {levels}"
            ),
        });
    }
    Ok(())
}

/// A Choice question names at most 255 options.
fn check_choice(id: &str, options: usize) -> Result<()> {
    if options > MAX_CHOICE_OPTIONS {
        return Err(Error::Question {
            id: id.to_string(),
            message: format!(
                "a Choice question names at most {MAX_CHOICE_OPTIONS} options, and this one names {options}"
            ),
        });
    }
    Ok(())
}

/// A question written out as JSON names a type, and a Choice or a Score names
/// criteria, the way the Python SDK checks a question dictionary.
fn check_raw(id: &str, value: &Value) -> Result<()> {
    let kind = value
        .get("type")
        .and_then(Value::as_str)
        .filter(|kind| !kind.is_empty())
        .ok_or_else(|| Error::Question {
            id: id.to_string(),
            message: "a question written out as JSON names a nonempty `type`".to_string(),
        })?;
    if matches!(kind, "choice" | "score") && value.get("criteria").is_none() {
        return Err(Error::Question {
            id: id.to_string(),
            message: format!("a {kind} question names `criteria`"),
        });
    }
    match kind {
        "score" => check_score(
            id,
            value
                .get("criteria")
                .and_then(Value::as_array)
                .map_or(0, Vec::len),
        ),
        "choice" => check_choice(
            id,
            value
                .get("criteria")
                .and_then(Value::as_object)
                .map_or(0, Map::len),
        ),
        _ => Ok(()),
    }
}

//! What a client is built from, and how a setting is resolved.
//!
//! Resolution follows both official SDKs: an explicit value, then the
//! environment variable, then the default. An environment value that is empty
//! or holds only whitespace is ignored, so an unset variable and a blank one
//! read the same.

use std::fmt;
use std::time::Duration;

use reqwest::header::HeaderMap;

use crate::error::Error;
use crate::retry::RetryPolicy;
use crate::{Result, defaults, env};

/// An API key that no log line, error, or `Debug` output carries.
///
/// ```
/// use jev::ApiKey;
///
/// let key = ApiKey::new("ts-secret-value");
/// assert_eq!(format!("{key:?}"), "***");
/// assert_eq!(key.to_string(), "***");
/// assert_eq!(key.expose(), "ts-secret-value");
/// ```
#[derive(Clone, PartialEq, Eq)]
pub struct ApiKey(String);

impl ApiKey {
    /// Hold a key.
    #[must_use]
    pub fn new<K: Into<String>>(key: K) -> Self {
        Self(key.into())
    }

    /// The key itself. Call this where the key has to go on the wire, and
    /// nowhere else.
    #[must_use]
    pub fn expose(&self) -> &str {
        &self.0
    }
}

impl fmt::Debug for ApiKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("***")
    }
}

impl fmt::Display for ApiKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str("***")
    }
}

impl From<&str> for ApiKey {
    fn from(key: &str) -> Self {
        Self::new(key)
    }
}

impl From<String> for ApiKey {
    fn from(key: String) -> Self {
        Self::new(key)
    }
}

/// The settings a client is built from. Every setting a caller leaves out is
/// read from the environment, and then from the defaults.
///
/// ```
/// use std::time::Duration;
///
/// use jev::Config;
///
/// let config = Config::new()
///     .api_key("ts-secret-value")
///     .base_url("https://api.typesafe.ai")
///     .timeout(Duration::from_secs(5));
/// ```
#[derive(Debug, Clone, Default)]
pub struct Config {
    api_key: Option<ApiKey>,
    base_url: Option<String>,
    default_model: Option<String>,
    timeout: Option<Duration>,
    retry: Option<RetryPolicy>,
    default_headers: HeaderMap,
    http_client: Option<reqwest::Client>,
}

impl Config {
    /// Settings that come from the environment and the defaults alone.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// The key to send. Read from `TYPESAFE_API_KEY` when left out.
    #[must_use]
    pub fn api_key<K: Into<ApiKey>>(mut self, key: K) -> Self {
        self.api_key = Some(key.into());
        self
    }

    /// The API root. Read from `TYPESAFE_BASE_URL` when left out, and
    /// `https://api.typesafe.ai` when neither is set. Trailing slashes are
    /// dropped.
    #[must_use]
    pub fn base_url<U: Into<String>>(mut self, url: U) -> Self {
        self.base_url = Some(url.into());
        self
    }

    /// The model a request that names none asks. Read from
    /// `TYPESAFE_DEFAULT_MODEL` when left out, and `jev-latest` when neither is
    /// set.
    #[must_use]
    pub fn default_model<M: Into<String>>(mut self, model: M) -> Self {
        self.default_model = Some(model.into());
        self
    }

    /// How long one attempt may take, including reading its body. Ten seconds
    /// when left out.
    #[must_use]
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }

    /// What to retry and how long to wait. The defaults of both official SDKs
    /// when left out.
    #[must_use]
    pub fn retry(mut self, retry: RetryPolicy) -> Self {
        self.retry = Some(retry);
        self
    }

    /// Headers every request carries. A per-call header replaces one of these,
    /// and neither replaces the headers the API reads to identify the request.
    #[must_use]
    pub fn default_headers(mut self, headers: HeaderMap) -> Self {
        self.default_headers = headers;
        self
    }

    /// The HTTP client to send through, for a caller that configures its own
    /// proxy, pool, or TLS. A client of this crate's own when left out.
    #[must_use]
    pub fn http_client(mut self, client: reqwest::Client) -> Self {
        self.http_client = Some(client);
        self
    }

    /// Resolve every setting and check it.
    pub(crate) fn resolve(self) -> Result<Resolved> {
        let api_key = match self.api_key {
            Some(key) => key,
            None => ApiKey::new(from_env(env::API_KEY).ok_or_else(|| {
                Error::Config(format!(
                    "no API key was provided; pass `Config::api_key` or set {}",
                    env::API_KEY
                ))
            })?),
        };
        let base_url = self
            .base_url
            .or_else(|| from_env(env::BASE_URL))
            .unwrap_or_else(|| defaults::BASE_URL.to_string());
        let base_url = base_url.trim_end_matches('/').to_string();
        let parsed = url::Url::parse(&base_url)
            .map_err(|error| Error::Config(format!("`base_url` is not a URL: {error}")))?;
        if !matches!(parsed.scheme(), "http" | "https") {
            return Err(Error::Config(format!(
                "`base_url` uses the {} scheme, and the API speaks http or https",
                parsed.scheme()
            )));
        }
        let default_model = self
            .default_model
            .or_else(|| from_env(env::DEFAULT_MODEL))
            .unwrap_or_else(|| defaults::MODEL.to_string());
        let timeout = self.timeout.unwrap_or(defaults::TIMEOUT);
        if timeout.is_zero() {
            return Err(Error::Config(
                "`timeout` must be a positive duration".to_string(),
            ));
        }
        let retry = self.retry.unwrap_or_default();
        retry.validate()?;
        let http = match self.http_client {
            Some(client) => client,
            None => reqwest::Client::builder().build().map_err(|error| {
                Error::Config(format!("the HTTP client failed to build: {error}"))
            })?,
        };
        Ok(Resolved {
            api_key,
            base_url,
            default_model,
            timeout,
            retry,
            default_headers: self.default_headers,
            http,
        })
    }
}

/// Every setting, resolved and checked.
pub(crate) struct Resolved {
    pub(crate) api_key: ApiKey,
    pub(crate) base_url: String,
    pub(crate) default_model: String,
    pub(crate) timeout: Duration,
    pub(crate) retry: RetryPolicy,
    pub(crate) default_headers: HeaderMap,
    pub(crate) http: reqwest::Client,
}

/// One environment value, trimmed. An empty or whitespace-only value reads as
/// unset, the way both official SDKs read it.
fn from_env(name: &str) -> Option<String> {
    std::env::var(name)
        .ok()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

//! The retry policy, its delay, and the server delay headers it honors.
//!
//! The defaults are the ones both official SDKs ship: two retries, 500 ms
//! doubling to 5 s with a quarter of each delay taken off at random, and the
//! statuses a server sends when a later attempt can succeed.

use std::collections::HashSet;
use std::fmt;
use std::sync::Arc;
use std::time::{Duration, SystemTime};

use reqwest::header::HeaderMap;

use crate::Result;
use crate::error::Error;

/// The header a server sends to ask for a wait in milliseconds. It wins over
/// `Retry-After`, as it does in both official SDKs.
const RETRY_AFTER_MS_HEADER: &str = "retry-after-ms";

/// The header a server sends to ask for a wait in seconds or as a date.
const RETRY_AFTER_HEADER: &str = "retry-after";

/// The header an attempt after the first carries.
pub(crate) const RETRY_COUNT_HEADER: &str = "x-typesafe-retry-count";

/// A caller's own test of whether a failure is worth another attempt.
pub type RetryPredicate = Arc<dyn Fn(&Error) -> bool + Send + Sync>;

/// What to retry, how long to wait, and when to stop.
///
/// Every field is public so a caller builds one with struct update syntax over
/// the default or over the client's own policy:
///
/// ```
/// use jev::RetryPolicy;
///
/// let policy = RetryPolicy {
///     max_retries: 4,
///     ..RetryPolicy::default()
/// };
/// assert_eq!(policy.backoff_jitter, 0.25);
/// ```
#[derive(Clone)]
pub struct RetryPolicy {
    /// Attempts after the first. Zero retries nothing.
    pub max_retries: u32,
    /// The first delay, doubled each attempt up to `backoff_max`.
    pub backoff_initial: Duration,
    /// The longest delay the doubling reaches.
    pub backoff_max: Duration,
    /// The fraction of each delay taken off at random, from 0 to 1.
    pub backoff_jitter: f64,
    /// The statuses a retry follows.
    pub http_statuses: HashSet<u16>,
    /// Whether a server delay header replaces the computed delay.
    pub respect_retry_after: bool,
    /// The longest server delay honored. A longer one falls back to the
    /// computed delay.
    pub max_retry_after: Duration,
    /// Whether a request that never reached the API is retried.
    pub connection_errors: bool,
    /// Whether an attempt that ran past its timeout is retried.
    pub timeouts: bool,
    /// The whole call's budget, as a monotonic deadline measured from the
    /// first attempt's dispatch: the first attempt, every retry, every wait
    /// between them, and the body a read path consumes all share it. Each
    /// attempt's timeout is capped at the time the call has left, so a reply
    /// that arrives past the deadline ends as [`Error::Timeout`] rather than
    /// succeeding, and a retry whose delay would reach the deadline does not
    /// run — the last failure is returned. `None`, the default, sets no
    /// budget.
    pub budget: Option<Duration>,
    /// A caller's own test, asked in addition to the rules above.
    pub predicate: Option<RetryPredicate>,
}

impl Default for RetryPolicy {
    fn default() -> Self {
        let mut http_statuses: HashSet<u16> = (500..=599).collect();
        http_statuses.insert(408);
        http_statuses.insert(429);
        Self {
            max_retries: 2,
            backoff_initial: Duration::from_millis(500),
            backoff_max: Duration::from_secs(5),
            backoff_jitter: 0.25,
            http_statuses,
            respect_retry_after: true,
            max_retry_after: Duration::from_secs(60),
            connection_errors: true,
            timeouts: true,
            budget: None,
            predicate: None,
        }
    }
}

impl fmt::Debug for RetryPolicy {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut statuses: Vec<u16> = self.http_statuses.iter().copied().collect();
        statuses.sort_unstable();
        f.debug_struct("RetryPolicy")
            .field("max_retries", &self.max_retries)
            .field("backoff_initial", &self.backoff_initial)
            .field("backoff_max", &self.backoff_max)
            .field("backoff_jitter", &self.backoff_jitter)
            .field("http_statuses", &statuses)
            .field("respect_retry_after", &self.respect_retry_after)
            .field("max_retry_after", &self.max_retry_after)
            .field("connection_errors", &self.connection_errors)
            .field("timeouts", &self.timeouts)
            .field("budget", &self.budget)
            .field("predicate", &self.predicate.as_ref().map(|_| "set"))
            .finish()
    }
}

impl RetryPolicy {
    /// Check every field, the way both official SDKs check theirs.
    ///
    /// # Errors
    ///
    /// Returns [`Error::Config`] when the jitter falls outside 0 to 1, a
    /// status falls outside 100 to 999, or the budget is zero.
    pub fn validate(&self) -> Result<()> {
        if !(0.0..=1.0).contains(&self.backoff_jitter) {
            return Err(Error::Config(format!(
                "`retry.backoff_jitter` must be between 0 and 1, got {}",
                self.backoff_jitter
            )));
        }
        if let Some(status) = self
            .http_statuses
            .iter()
            .find(|status| !(100..=999).contains(*status))
        {
            return Err(Error::Config(format!(
                "`retry.http_statuses` must hold HTTP status codes, got {status}"
            )));
        }
        if self.budget == Some(Duration::ZERO) {
            return Err(Error::Config(
                "`retry.budget` must be a positive duration".to_string(),
            ));
        }
        Ok(())
    }

    /// Whether a status is one this policy retries.
    #[must_use]
    pub fn retries_status(&self, status: u16) -> bool {
        self.http_statuses.contains(&status)
    }

    /// Whether a failure is one this policy retries.
    #[must_use]
    pub fn retries_error(&self, error: &Error) -> bool {
        let built_in = match error {
            Error::Timeout { .. } => self.timeouts,
            Error::Connection { .. } => self.connection_errors,
            Error::Api(api) => self.retries_status(api.status),
            _ => false,
        };
        built_in
            || self
                .predicate
                .as_ref()
                .is_some_and(|predicate| predicate(error))
    }

    /// The wait before the retry that follows a zero-based attempt.
    #[must_use]
    pub fn delay(&self, attempt: u32, headers: Option<&HeaderMap>) -> Duration {
        self.delay_with(attempt, headers, rand::random::<f64>())
    }

    /// [`RetryPolicy::delay`] with the random draw supplied, so a test reads a
    /// fixed delay.
    #[must_use]
    pub fn delay_with(&self, attempt: u32, headers: Option<&HeaderMap>, random: f64) -> Duration {
        if self.respect_retry_after
            && let Some(asked) = headers.and_then(parse_retry_after)
            && asked <= self.max_retry_after
        {
            return asked;
        }
        let doubled = match 1u32.checked_shl(attempt) {
            Some(factor) => self.backoff_initial.saturating_mul(factor),
            None => self.backoff_max,
        }
        .min(self.backoff_max);
        let scale = 1.0 - random.clamp(0.0, 1.0) * self.backoff_jitter;
        Duration::try_from_secs_f64(doubled.as_secs_f64() * scale).unwrap_or(doubled)
    }
}

/// The wait a response asks for, read from `retry-after-ms` first and
/// `Retry-After` second.
///
/// `Retry-After` carries either a count of seconds or an HTTP date. A negative
/// count and an unreadable value name no wait.
#[must_use]
pub fn parse_retry_after(headers: &HeaderMap) -> Option<Duration> {
    parse_retry_after_at(headers, SystemTime::now())
}

/// [`parse_retry_after`] against a fixed `now`, so a test reads a date header
/// without waiting for the clock.
#[must_use]
pub fn parse_retry_after_at(headers: &HeaderMap, now: SystemTime) -> Option<Duration> {
    if let Some(raw) = header(headers, RETRY_AFTER_MS_HEADER)
        && let Some(delay) = parse_seconds(raw, 0.001)
    {
        return Some(delay);
    }
    let raw = header(headers, RETRY_AFTER_HEADER)?;
    if let Some(delay) = parse_seconds(raw, 1.0) {
        return Some(delay);
    }
    if raw.trim().parse::<f64>().is_ok() {
        // A readable count that is negative asks for no wait.
        return None;
    }
    let at = httpdate::parse_http_date(raw.trim()).ok()?;
    Some(at.duration_since(now).unwrap_or(Duration::ZERO))
}

/// One header as text, when the response carries it and it is text.
fn header<'a>(headers: &'a HeaderMap, name: &str) -> Option<&'a str> {
    headers.get(name).and_then(|value| value.to_str().ok())
}

/// A count of units, scaled to seconds. A blank value counts as zero, the way
/// the Python SDK reads it.
fn parse_seconds(raw: &str, unit: f64) -> Option<Duration> {
    let trimmed = raw.trim();
    let count: f64 = if trimmed.is_empty() {
        0.0
    } else {
        trimmed.parse().ok()?
    };
    if !count.is_finite() || count < 0.0 {
        return None;
    }
    Duration::try_from_secs_f64(count * unit).ok()
}

//! The models the account can ask.

use std::time::Duration;

use reqwest::header::HeaderMap;
use serde::{Deserialize, Serialize};

use crate::Result;
use crate::client::Client;
use crate::error::Error;
use crate::retry::RetryPolicy;

/// One model the account can ask.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize, Serialize)]
pub struct ModelCard {
    /// The name a request names in `model`.
    pub name: String,
    /// What the model is for, as TypeSafe describes it.
    #[serde(default)]
    pub description: String,
    /// The day the model was released, as the API writes it.
    #[serde(default)]
    pub release_date: String,
}

/// What one listing overrides on the client.
#[derive(Debug, Clone, Default)]
pub struct ListOptions {
    pub(crate) retry: Option<RetryPolicy>,
    pub(crate) timeout: Option<Duration>,
    pub(crate) headers: HeaderMap,
}

impl ListOptions {
    /// Options that override nothing.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Retry this listing by another policy.
    #[must_use]
    pub fn retry(mut self, retry: RetryPolicy) -> Self {
        self.retry = Some(retry);
        self
    }

    /// Give each attempt of this listing another timeout.
    #[must_use]
    pub fn timeout(mut self, timeout: Duration) -> Self {
        self.timeout = Some(timeout);
        self
    }

    /// Add headers to this listing.
    #[must_use]
    pub fn headers(mut self, headers: HeaderMap) -> Self {
        self.headers = headers;
        self
    }
}

/// The models resource, reached through [`Client::models`].
#[derive(Debug)]
pub struct Models<'a> {
    client: &'a Client,
}

impl<'a> Models<'a> {
    /// Reach the resource through a client.
    pub(crate) fn new(client: &'a Client) -> Self {
        Self { client }
    }

    /// List the models the account can ask.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Client::system_one`], and
    /// [`Error::ResponseValidation`] when the body does not carry a list of
    /// models, naming the field at fault the way the Python SDK does:
    /// `models`, or `models[i].field` for one card.
    pub async fn list(&self, options: ListOptions) -> Result<Vec<ModelCard>> {
        let raw = self.client.list_models(options).await?;
        let body: serde_json::Value =
            serde_json::from_slice(&raw.bytes).map_err(|_| invalid(&raw, "models"))?;
        let cards = body
            .get("models")
            .and_then(serde_json::Value::as_array)
            .ok_or_else(|| invalid(&raw, "models"))?;
        cards
            .iter()
            .enumerate()
            .map(|(at, card)| read_card(&raw, at, card))
            .collect()
    }

    /// List the models the account can ask, handing back the response unread,
    /// the way `models.list().asResponse()` does in the JavaScript SDK and
    /// `raw_http_response` does in the Python SDK.
    ///
    /// # Errors
    ///
    /// Returns the same errors as [`Models::list`], other than
    /// [`Error::ResponseValidation`].
    pub async fn list_raw(&self, options: ListOptions) -> Result<crate::RawResponse> {
        self.client.list_models(options).await
    }
}

/// One card of the listing, or the field that stopped it.
fn read_card(raw: &crate::RawResponse, at: usize, card: &serde_json::Value) -> Result<ModelCard> {
    let object = card
        .as_object()
        .ok_or_else(|| invalid(raw, format!("models[{at}]")))?;
    let read = |field: &str| {
        object
            .get(field)
            .and_then(serde_json::Value::as_str)
            .map(str::to_string)
            .ok_or_else(|| invalid(raw, format!("models[{at}].{field}")))
    };
    Ok(ModelCard {
        name: read("name")?,
        description: read("description")?,
        release_date: read("release_date")?,
    })
}

/// The error a body that is not a model listing raises.
fn invalid(raw: &crate::RawResponse, field_path: impl Into<String>) -> Error {
    Error::ResponseValidation {
        status: raw.status,
        field_path: field_path.into(),
        body: raw.body().map(Box::new),
        request_id: raw.request_id().map(str::to_string),
    }
}
